"""Canonical interview UI with synthetic data, six profiles, three devices and themes."""
import json,os
from pathlib import Path
from playwright.sync_api import sync_playwright
URL=os.environ.get('GS_TEST_URL','http://127.0.0.1:8765/index.html');ORIGIN=URL.split('/index.html')[0];K='grupo_saude_v4_demo_2'
OUT=Path(os.environ.get('GS_TEST_ARTIFACTS','/tmp/interview-artifacts'));OUT.mkdir(parents=True,exist_ok=True);rows=[];scope={}
def check(name,value):
 rows.append({**scope,'case':name,'state':'Aprovada' if value else 'Falhou'});print(name,bool(value),flush=True);assert value,name
def candidate(page):return page.evaluate('(k)=>JSON.parse(localStorage.getItem(k)).candidates[0]',K)
